const label = (sib: string) => { if (LABELS[sib]) return LABELS[sib]!; if (/^Confirm which files in .* are needed at runtime/.test(sib)) return "runtime check"; if (/^Check the package manifest for/.test(sib)) return "manifest check"; if (/^List the runtime imports/.test(sib)) return "runtime import list"; if (/^Confirm with the package owner/.test(sib)) return "owner confirmation"; return short(sib); };
function ledgerFor(domain: string, i: number, w: string, siblings: string[], decision: string): string[] { const o = pick(OPEN[domain] ?? OPEN["tool-selection"]!, i); return pick(LEDGER_FORMS, i)(o, w, label(siblings[0]!), label(siblings[1]!), sentence(decision)); }
const hasTerm = (text: string, term: string) => new RegExp(`(^|[^a-z0-9])${term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?=$|[^a-z0-9])`, "i").test(text);

